// MSL port of nvn_bc1astc.c (same block layouts, same choices; probe-bc1astc checks the two are byte-identical).
// kernel bc1astc: one thread per 4x4 block. buffer(0) BC1 blocks, buffer(1) parameters, buffer(2) ASTC blocks.
#pragma once
static const char k_bc1astc_msl[] =
"#include <metal_stdlib>\nusing namespace metal;\n"
"struct BP { uint src_off, src_pitch, w, h, rgba, dst_off; };\n"
"static void put(thread uchar *b, uint pos, uint n, uint v) { for (uint i = 0; i < n; i++) if ((v >> i) & 1) b[(pos + i) >> 3] |= uchar(1u << ((pos + i) & 7)); }\n"
"static void putw(thread uchar *b, uint pos, uint n, uint v) { for (uint i = 0; i < n; i++) if ((v >> i) & 1) { uint bit = 127 - (pos + i); b[bit >> 3] |= uchar(1u << (bit & 7)); } }\n"
"static int x5(int v) { return (v << 3) | (v >> 2); }\n"
"static int x6(int v) { return (v << 2) | (v >> 4); }\n"
"static void emit(thread uchar *o, int cem, int dual, int wbits, thread int *e0, thread int *e1, thread int *w) {\n"
"  int nw = dual ? 32 : 16, wmax = (1 << wbits) - 1;\n"
"  if (e1[0] + e1[1] + e1[2] < e0[0] + e0[1] + e0[2]) { for (int c = 0; c < 4; c++) { int t = e0[c]; e0[c] = e1[c]; e1[c] = t; } for (int i = 0; i < nw; i++) w[i] = wmax - w[i]; }\n"
"  for (int i = 0; i < 16; i++) o[i] = 0;\n"
"  put(o, 0, 11, dual ? 0x441u : (wbits == 2 ? 0x042u : 0x053u)); put(o, 13, 4, uint(cem));\n"
"  uint pos = 17; int nc = cem == 12 ? 4 : 3;\n"
"  for (int c = 0; c < nc; c++) { put(o, pos, 8, uint(e0[c])); put(o, pos + 8, 8, uint(e1[c])); pos += 16; }\n"
"  for (int i = 0; i < nw; i++) putw(o, uint(i * wbits), uint(wbits), uint(w[i]));\n"
"  if (dual) put(o, 128 - uint(nw * wbits) - 2, 2, 3u);\n"
"}\n"
"kernel void bc1astc(device const uchar *src [[buffer(0)]], device const BP &p [[buffer(1)]], device uchar *dst [[buffer(2)]], uint2 g [[thread_position_in_grid]]) {\n"
"  uint bw = (p.w + 3) / 4, bh = (p.h + 3) / 4; if (g.x >= bw || g.y >= bh) return;\n"
"  device const uchar *bc = src + p.src_off + g.y * p.src_pitch + g.x * 8;\n"
"  int c0 = bc[0] | (bc[1] << 8), c1 = bc[2] | (bc[3] << 8); uint ix = uint(bc[4]) | (uint(bc[5]) << 8) | (uint(bc[6]) << 16) | (uint(bc[7]) << 24);\n"
"  int p0[3] = {x5(c0 >> 11), x6((c0 >> 5) & 63), x5(c0 & 31)}, p1[3] = {x5(c1 >> 11), x6((c1 >> 5) & 63), x5(c1 & 31)};\n"
"  int idx[16], used = 0; for (int k = 0; k < 16; k++) { idx[k] = int((ix >> (2 * k)) & 3); used |= 1 << idx[k]; }\n"
"  int e0[4] = {p0[0], p0[1], p0[2], 255}, e1[4] = {p1[0], p1[1], p1[2], 255}, w[32]; uchar o[16];\n"
"  if (c0 > c1) { const int map[4] = {0, 3, 1, 2}; for (int k = 0; k < 16; k++) w[k] = map[idx[k]]; emit(o, 8, 0, 2, e0, e1, w); }\n"
"  else if (!(used & 8)) {\n"
"    const int unq[2][8] = {{0, 21, 43, 64, 0, 0, 0, 0}, {0, 9, 18, 27, 37, 46, 55, 64}};\n"
"    int cnt[3] = {0, 0, 0}; for (int k = 0; k < 16; k++) cnt[idx[k]]++;\n"
"    int mid[3] = {(p0[0] + p1[0] + 1) / 2, (p0[1] + p1[1] + 1) / 2, (p0[2] + p1[2] + 1) / 2};\n"
"    long best = -1; int bb = 2, bwa = 0, bwb = 1, bwc = 3, be0[3] = {0, 0, 0}, be1[3] = {0, 0, 0};\n"
"    for (int bits = 2; bits <= 3; bits++) { int n = 1 << bits;\n"
"      for (int wa = 0; wa < n; wa++) for (int wb = wa + 1; wb < n; wb++) for (int wc = wb + 1; wc < n; wc++) {\n"
"        int f0[3], f1[3]; bool ok = true; long err = 0;\n"
"        for (int c = 0; c < 3 && ok; c++) {\n"
"          int d = p1[c] - p0[c], span = unq[bits - 2][wc] - unq[bits - 2][wa];\n"
"          int L = (64 * d + (d >= 0 ? span / 2 : -span / 2)) / span;\n"
"          f0[c] = p0[c] - (unq[bits - 2][wa] * L + (L >= 0 ? 32 : -32)) / 64; f1[c] = f0[c] + L;\n"
"          if (f0[c] < 0 || f0[c] > 255 || f1[c] < 0 || f1[c] > 255) ok = false;\n"
"          int want[3] = {p0[c], p1[c], mid[c]}, wt[3] = {unq[bits - 2][wa], unq[bits - 2][wc], unq[bits - 2][wb]};\n"
"          for (int i = 0; ok && i < 3; i++) { int r = ((f0[c] * 257 * (64 - wt[i]) + f1[c] * 257 * wt[i] + 32) >> 6) >> 8; long e = r - want[i]; err += e * e * cnt[i]; }\n"
"        }\n"
"        if (ok && (best < 0 || err < best)) { best = err; bb = bits; bwa = wa; bwb = wb; bwc = wc; for (int c = 0; c < 3; c++) { be0[c] = f0[c]; be1[c] = f1[c]; } }\n"
"      } }\n"
"    int f0[4] = {be0[0], be0[1], be0[2], 255}, f1[4] = {be1[0], be1[1], be1[2], 255};\n"
"    if (best < 0) { for (int c = 0; c < 4; c++) { f0[c] = e0[c]; f1[c] = e1[c]; } bb = 3; bwa = 0; bwb = 3; bwc = 7; }\n"
"    const int map[3] = {bwa, bwc, bwb}; for (int k = 0; k < 16; k++) w[k] = map[idx[k]]; emit(o, 8, 0, bb, f0, f1, w);\n"
"  } else {\n"
"    int rgba = int(p.rgba);\n"
"    int pal[4][3] = {{p0[0], p0[1], p0[2]}, {p1[0], p1[1], p1[2]}, {(p0[0] + p1[0] + 1) / 2, (p0[1] + p1[1] + 1) / 2, (p0[2] + p1[2] + 1) / 2}, {0, 0, 0}};\n"
"    int colours = used & (rgba ? 7 : 15); int ba = 0, bb = 1; long best = -1;\n"
"    for (int a = 0; a < 4; a++) for (int b = a; b < 4; b++) {\n"
"      if (!((colours >> a) & 1) || !((colours >> b) & 1)) continue; long err = 0;\n"
"      for (int k = 0; k < 16; k++) { int i = idx[k]; if (!((colours >> i) & 1)) continue; long da = 0, db = 0;\n"
"        for (int c = 0; c < 3; c++) { int x = pal[i][c] - pal[a][c], y = pal[i][c] - pal[b][c]; da += x * x; db += y * y; } err += da < db ? da : db; }\n"
"      if (best < 0 || err < best) { best = err; ba = a; bb = b; } }\n"
"    int f0[4] = {pal[ba][0], pal[ba][1], pal[ba][2], 255}, f1[4] = {pal[bb][0], pal[bb][1], pal[bb][2], rgba ? 0 : 255};\n"
"    for (int k = 0; k < 16; k++) { int i = idx[k], cw = 0;\n"
"      if ((colours >> i) & 1) { long da = 0, db = 0; for (int c = 0; c < 3; c++) { int x = pal[i][c] - f0[c], y = pal[i][c] - f1[c]; da += x * x; db += y * y; } cw = db < da ? 1 : 0; }\n"
"      w[2 * k] = cw; w[2 * k + 1] = (rgba && i == 3) ? 1 : 0; }\n"
"    emit(o, 12, 1, 1, f0, f1, w);\n"
"  }\n"
"  device uchar *d = dst + p.dst_off + (g.y * bw + g.x) * 16; for (int i = 0; i < 16; i++) d[i] = o[i];\n"
"}\n";
